package net.officefloor.hq.app.voidreason;

import jakarta.validation.Valid;
import jakarta.validation.constraints.NotBlank;
import jakarta.validation.constraints.Pattern;
import jakarta.validation.constraints.Size;
import java.util.List;
import net.officefloor.hq.app.SignedIn;
import org.springframework.dao.DataIntegrityViolationException;
import org.springframework.http.HttpStatus;
import org.springframework.validation.annotation.Validated;
import org.springframework.web.bind.annotation.ExceptionHandler;
import org.springframework.web.bind.annotation.GetMapping;
import org.springframework.web.bind.annotation.PathVariable;
import org.springframework.web.bind.annotation.PostMapping;
import org.springframework.web.bind.annotation.RequestBody;
import org.springframework.web.bind.annotation.RequestHeader;
import org.springframework.web.bind.annotation.RequestMapping;
import org.springframework.web.bind.annotation.ResponseStatus;
import org.springframework.web.bind.annotation.RestController;

@RestController
@RequestMapping("/api/sheets/{sheetId}/void-reasons")
@Validated
public class VoidReasonController {

    /** What the screen is told about a void reason: its text. */
    public record VoidReasonView(long id, String reason) {

        static VoidReasonView of(VoidReason reason) {
            return new VoidReasonView(reason.getId(), reason.getReason());
        }
    }

    /** A void reason as entered on the form: text, not blank. */
    public record VoidReasonForm(@NotBlank @Size(max = 100) String reason) {
    }

    private final VoidReasonService service;

    public VoidReasonController(VoidReasonService service) {
        this.service = service;
    }

    /** The sheet's void reasons in the order they were added. */
    @GetMapping
    public List<VoidReasonView> list(
            @PathVariable @NotBlank @Size(max = 64) @Pattern(regexp = "[A-Za-z0-9._-]+") String sheetId) {
        return service.list(sheetId).stream().map(VoidReasonView::of).toList();
    }

    /** Add a void reason to the sheet. */
    @PostMapping
    public VoidReasonView add(
            @PathVariable @NotBlank @Size(max = 64) @Pattern(regexp = "[A-Za-z0-9._-]+") String sheetId,
            @RequestHeader(SignedIn.HEADER) @NotBlank @Size(max = 200) String user,
            @RequestBody @Valid VoidReasonForm form) {
        return VoidReasonView.of(service.add(sheetId, SignedIn.name(user), form.reason()));
    }

    /** Another user added the reason between the check and the write: the unique index refuses it. */
    @ExceptionHandler(DataIntegrityViolationException.class)
    @ResponseStatus(HttpStatus.CONFLICT)
    public void reasonTaken() {
    }
}
package net.officefloor.hq.app.voidreason;

import jakarta.persistence.Column;
import jakarta.persistence.Entity;
import jakarta.persistence.GeneratedValue;
import jakarta.persistence.GenerationType;
import jakarta.persistence.Id;
import jakarta.persistence.Table;

/** A void reason on a sheet: trimmed text, on the sheet's list at most once. */
@Entity
@Table(name = "void_reason")
public class VoidReason {

    @Id
    @GeneratedValue(strategy = GenerationType.IDENTITY)
    private Long id;

    @Column(name = "sheet_id", nullable = false)
    private String sheetId;

    @Column(name = "reason", nullable = false)
    private String reason;

    protected VoidReason() {
    }

    public VoidReason(String sheetId, String reason) {
        this.sheetId = sheetId;
        this.reason = reason;
    }

    public Long getId() {
        return id;
    }

    public String getSheetId() {
        return sheetId;
    }

    public String getReason() {
        return reason;
    }
}
package net.officefloor.hq.app.voidreason;

import java.util.List;
import org.springframework.data.jpa.repository.JpaRepository;

public interface VoidReasonRepository extends JpaRepository<VoidReason, Long> {

    /** The sheet's void reasons in the order they were added. */
    List<VoidReason> findBySheetIdOrderByIdAsc(String sheetId);

    /** Whether the reason is already on the sheet's list. */
    boolean existsBySheetIdAndReason(String sheetId, String reason);
}
package net.officefloor.hq.app.voidreason;

import java.util.List;
import net.officefloor.hq.app.Audit;
import net.officefloor.hq.app.sheet.SheetService;
import org.springframework.http.HttpStatus;
import org.springframework.stereotype.Service;
import org.springframework.transaction.annotation.Transactional;
import org.springframework.web.server.ResponseStatusException;

/** The void reasons on a sheet: listed, added, and the check a void's reason is one of them. */
@Service
public class VoidReasonService {

    private final VoidReasonRepository reasons;
    private final SheetService sheets;
    private final Audit audit;

    public VoidReasonService(VoidReasonRepository reasons, SheetService sheets, Audit audit) {
        this.reasons = reasons;
        this.sheets = sheets;
        this.audit = audit;
    }

    /** The sheet's void reasons in the order they were added. */
    @Transactional(readOnly = true)
    public List<VoidReason> list(String sheetId) {
        return reasons.findBySheetIdOrderByIdAsc(sheetId);
    }

    /** Add a void reason (trimmed) to the sheet; refused when blank or already on its list. */
    @Transactional
    public VoidReason add(String sheetId, String user, String reason) {
        String text = reason == null ? "" : reason.trim();
        if (text.isEmpty()) {
            throw new ResponseStatusException(HttpStatus.BAD_REQUEST, "A void reason cannot be blank.");
        }
        // Take the sheet's lock first, so the same reason added twice at once cannot both pass the check.
        sheets.lock(sheetId);
        if (reasons.existsBySheetIdAndReason(sheetId, text)) {
            throw new ResponseStatusException(HttpStatus.CONFLICT, "That reason is already on this sheet's list.");
        }
        VoidReason saved = reasons.saveAndFlush(new VoidReason(sheetId, text));
        audit.recordOnCommit("VOID_REASON_ADDED sheet=" + sheetId + " by=" + user + " reason=" + text);
        return saved;
    }

    /**
     * The reason a claim is voided with: none while the sheet's list is empty and none is given; refused
     * when the list is not empty and none is given, or when the one given is not on the list.
     */
    @Transactional(readOnly = true)
    public String require(String sheetId, String reason) {
        String text = reason == null ? "" : reason.trim();
        List<String> listed = list(sheetId).stream().map(VoidReason::getReason).toList();
        if (text.isEmpty()) {
            if (!listed.isEmpty()) {
                throw new ResponseStatusException(HttpStatus.CONFLICT, "Choose a reason from the list to void the claim.");
            }
            return null;
        }
        if (!listed.contains(text)) {
            throw new ResponseStatusException(HttpStatus.CONFLICT, "The reason is not on this sheet's list.");
        }
        return text;
    }
}
-- A void reason on a sheet: trimmed text, on the sheet's list at most once. While the list is not
-- empty a claim is voided only with a reason from it, which the claim keeps (null: voided without one).
CREATE TABLE void_reason (
    id       BIGINT AUTO_INCREMENT PRIMARY KEY,
    sheet_id VARCHAR(64)  NOT NULL REFERENCES sheet (id),
    reason   VARCHAR(100) NOT NULL
);
CREATE UNIQUE INDEX void_reason_sheet_reason ON void_reason (sheet_id, reason);
ALTER TABLE claim ADD COLUMN void_reason VARCHAR(100);
-- A person's aliases: other names they go by, each kept with surrounding spaces removed and with
-- its key (ignoring case). An alias shares the names' uniqueness on the sheet: no alias equals,
-- by key, any name or other alias there.
CREATE TABLE person_alias (
    person_id BIGINT       NOT NULL REFERENCES person (id),
    alias     VARCHAR(200) NOT NULL,
    alias_key VARCHAR(200) NOT NULL,
    PRIMARY KEY (person_id, alias_key)
);
import { HttpClient } from '@angular/common/http';
import { Injectable, effect, inject, signal, untracked } from '@angular/core';
import { firstValueFrom } from 'rxjs';
import { Session } from './session';

/** A void reason on the sheet: while the list is not empty, a claim is voided only with one of them. */
export interface VoidReasonView {
  id: number;
  /** Trimmed; on the sheet's list at most once. */
  reason: string;
}

// The sheet's void reasons, read from and written to the store.
@Injectable({ providedIn: 'root' })
export class VoidReasonsApi {
  private readonly http = inject(HttpClient);

  /** The sheet's void reasons in the order they were added. */
  list(sheet: string): Promise<VoidReasonView[]> {
    return firstValueFrom(this.http.get<VoidReasonView[]>(this.url(sheet)));
  }

  /** Add a void reason; refused when blank or already on the list. */
  add(sheet: string, reason: string): Promise<VoidReasonView> {
    return firstValueFrom(this.http.post<VoidReasonView>(this.url(sheet), { reason }));
  }

  private url(sheet: string): string {
    return `/api/sheets/${encodeURIComponent(sheet)}/void-reasons`;
  }
}

// The active sheet's void reasons, shared by the list, each claim's void and the summary; re-read
// from the store on every sheet load.
@Injectable({ providedIn: 'root' })
export class VoidReasons {
  private readonly session = inject(Session);
  private readonly api = inject(VoidReasonsApi);

  readonly list = signal<VoidReasonView[]>([]);

  constructor() {
    effect(() => {
      const sheet = this.session.sheet();
      const loads = this.session.loads();
      untracked(() => {
        this.list.set([]);
        if (sheet) void this.reload(sheet, loads);
      });
    });
  }

  /** Add a void reason to the active sheet's list. */
  async add(sheet: string, reason: string): Promise<void> {
    const saved = await this.api.add(sheet, reason);
    if (this.session.sheet() === sheet) this.list.update((all) => [...all, saved]);
  }

  private async reload(sheet: string, loads: number): Promise<void> {
    const reasons = await this.api.list(sheet);
    // A later load may have started while this one was in flight: only the latest is shown.
    if (this.session.sheet() === sheet && this.session.loads() === loads) this.list.set(reasons);
  }
}
import { Component, effect, inject, signal, untracked } from '@angular/core';
import { VoidReasons } from '../../core/void-reasons';
import { Session } from '../../core/session';

// The sheet's void reasons, in the order they were added, and a form to add one; a blank reason or
// one already on the list is refused. While the list is not empty, a claim is voided only with one.
@Component({
  selector: 'app-void-reasons',
  template: `
    <section aria-labelledby="void-reasons-heading">
      <h2 id="void-reasons-heading">Void reasons</h2>
      <form (submit)="add($event)" aria-label="Add a void reason">
        <label for="void-reason-text">Reason</label>
        <input
          id="void-reason-text"
          data-testid="void-reason-text"
          [value]="text()"
          (input)="text.set(value($event)); error.set(null)"
        />
        <button type="submit" data-testid="void-reason-add">Add void reason</button>
        @if (error(); as message) {
          <p role="alert" data-testid="void-reason-error">{{ message }}</p>
        }
      </form>
      <ul aria-label="Void reasons">
        @for (r of reasons.list(); track r.id) {
          <li [attr.data-testid]="'void-reason-row-' + r.reason">{{ r.reason }}</li>
        }
      </ul>
    </section>
  `,
})
export class VoidReasonsList {
  private readonly session = inject(Session);
  protected readonly reasons = inject(VoidReasons);

  protected readonly text = signal('');
  protected readonly error = signal<string | null>(null);
  /** A submit is waiting for its answer: a second submit meanwhile is ignored. */
  private busy = false;

  constructor() {
    // A sheet load clears what was being entered on the last one.
    effect(() => {
      this.session.sheet();
      this.session.loads();
